contract MockToken {
    uint256 public totalCalls;
    function transferFrom(address, address, uint256) external returns (bool) {
        totalCalls++;
        return true;
    }
}

contract InvMutTest is Test {
    demo c;
    MockToken mock;
    function setUp() public { 
        c = new demo();
        mock = new MockToken();
    }
    function testRegression_property() public {
        address[] memory tos = new address[](2);
        tos[0] = address(mock);
        tos[1] = address(mock);
        address from = address(0x123);
        uint256 v = 100;

        c.transfer(from, address(mock), tos, v);

        assertTrue(mock.totalCalls() == 2);
    }
}
